package net.officefloor.hq.app.claim;

/** The number of the sheet's last bulk settle batch, "" when there has been none. */
public record SettleBatchResponse(String last) {
}

/** The sheet's claims, newest first. */
export function useClaims(sheet: string): Claim[] {
  const asOf = useAsOf();
  const { data } = useQuery({
    queryKey: claimsKey(sheet, asOf),
    queryFn: () => getJson<Claim[]>(readPath(`/api/sheets/${encodeURIComponent(sheet)}/claims`, asOf)),
    enabled: sheet !== '',
  });
  return data ?? [];
}

export const settleBatchKey = (sheet: string) => ['sheet', sheet, 'settle-batch'] as const;

/** The number of the sheet's last bulk settle batch, "" when there has been none. */
export function useLastSettleBatch(sheet: string): string {
  const { data } = useQuery({
    queryKey: settleBatchKey(sheet),
    queryFn: () => getJson<{ last: string }>(`/api/sheets/${encodeURIComponent(sheet)}/settle-batch`),
    enabled: sheet !== '',
  });
  return data?.last ?? '';
}

/** The amounts of the claims that count added up, shown with two decimals. Summed in whole cents
 *  so no float drift shows. */
function Home() {
  const [user] = useSearchParam('user', asString);
  const [sheet] = useSearchParam('sheet', asString);
  if (user === '') return <SignIn />;
  return (
    <>
      <CurrentUser />
      <SheetPicker />
      {sheet !== '' && (
        <div key={sheet}>
          <SheetHeader />
          <SheetToday />
          <AsOfControl />
          <RatePanel />
          <HolidayPanel />
          <VoidReasonPanel />
          <TemplatePanel />
          <SettingsPanel />
          <PeriodPanel />
          <PersonForm />
          <PeopleList />
          <PoolPanel />
          <AuditViewer />
        </div>
      )}
      {sheet === '' && <p data-testid="home-empty">Nothing here yet.</p>}
    </>
  );
}

